scwin.notice = function () {
    console.log(dma_logout.getJSON());
    const eventSource = new EventSource(`/InsWebApp/user/notice.pwkjson?userId=${dma_logout.get("id")}`);
    eventSource.addEventListener(dma_logout.get("id"), function (event) {

        fetchAndConvertToBase64("/InsWebApp/images/mobile/notice.svg")
            .then(base64 => {
                var callback = function (result) { console.log(result); };
                let cleaned = msg.replace(/"/g, "");  
                var opt = { "title": "오늘의 할일 메일", "message": cleaned, "icon": base64};
                $h.view.notification(callback, opt);
            })
            .catch(err => {
                console.error("인코딩 중 오류 발생:", err);
            });

    });

    eventSource.onopen = () => console.log("연결완료");
    eventSource.onerror = (err) => console.log("오류발생", err);
}
async function fetchAndConvertToBase64(url) {
    const response = await fetch(url);
    const blob = await response.blob();

    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result); // Data URL with Base64
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}

scwin.fetchAndConvertToBase64 = async function (url) {
    const response = await fetch(url);
    const blob = await response.blob();

    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result); // Data URL with Base64
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}

scwin.grp_logo_onclick = function (e) {
    scwin.notice_button_sendPush();
    //$p.url("/InsWebApp/ui/mobile/mainPage.xml");
};

scwin.dma_session_submitdone = function (e) {
    const responseData = e.responseJSON.userVo;
    dma_logout.set("id", responseData.userId);
    scwin.notice();
};


scwin.side_button_onclick = function (e) {
    const sideFrame = $p.parent().side_frame;

    if (!scwin.side) {
        sideFrame.addClass("active"); // 나타내기
        scwin.side = true;
    } else {
        sideFrame.removeClass("active"); // 숨기기
        scwin.side = false;
    }
};

scwin.side_button_touch = function () {
    let touchStartX = 0;

    document.addEventListener("touchstart", function (e) {
        touchStartX = e.touches[0].clientX;
    });

    document.addEventListener("touchend", function (e) {
        const touchEndX = e.changedTouches[0].clientX;
        const diffX = touchEndX - touchStartX;
        let comment = $p.parent().scwin.comment;

        // 오른쪽으로 스와이프 (예: 100px 이상이면 열기)
        if (diffX > 100 && !scwin.side && !comment) {
            const sideFrame = $p.parent().side_frame;
            sideFrame.addClass("active");
            scwin.side = true;
        }

        // 왼쪽으로 스와이프 (메뉴 열려 있을 때 닫기)
        if (diffX < -100 && scwin.side) {
            const sideFrame = $p.parent().side_frame;
            sideFrame.removeClass("active");
            scwin.side = false;
        }
    });


}

scwin.notice_button_sendPush = function (result) {

};
